typedef unsigned int u_int;

struct TimeStamp
{
    long pts;
    long dts;
    int pos;
    int len;
};

struct sceIpuDmaEnv
{
    int padding[7];
    u_int ipubp;
};

struct ViBuf
{
    void* data;
    void* tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
    long totalBytes;
    TimeStamp* ts;
    int n_ts;
    int count_ts;
    int wt_ts;
};

extern "C" int WaitSema(int);
extern "C" int SignalSema(int);

#define D4_MADR ((volatile u_int*)0x1000b410)
#define DGET_IPU_BP() (*(volatile u_int*)0x10002020)
#define VIBUF_ELM_SIZE 2048
#define TS_NONE (-1)
#define min(x,y) (((x) > (y))? (y): (x))

static inline int IsPtsInRegion( int tgt, int pos, int len, int size )
{
    int tgt1 = (tgt + size - pos) % size;
    return tgt1 < len;
}

static int viBufGetTs( ViBuf* f, TimeStamp* ts )
{
    u_int   d4madr = *D4_MADR, ipubp = DGET_IPU_BP(), d4madr_next, stop;
    int     bp, fp = (ipubp >> 16) & 0x3, ifc = (ipubp >> 8) & 0xf, datasize, isEnd = 0, tscount, wt;

    WaitSema( f->sema );
    bp = f->env.ipubp & 0x7f;
    d4madr_next = d4madr - ( (fp + ifc) << 4 );
    datasize =  VIBUF_ELM_SIZE * f->n;
    ts->pts = TS_NONE;
    ts->dts = TS_NONE;
    stop = ( d4madr_next + (bp >> 3) + datasize - (u_int)f->data ) % datasize;
    tscount = f->count_ts;
    wt = f->wt_ts;
    for( int i = 0; i < tscount && !isEnd; i++ )
    {
        int rd = ( wt - tscount + f->n_ts + i ) % f->n_ts;

        if( IsPtsInRegion(stop, f->ts[rd].pos, f->ts[rd].len, datasize) )
        {
            ts->pts = f->ts[rd].pts;
            ts->dts = f->ts[rd].dts;
            f->ts[rd].pts = TS_NONE;
            f->ts[rd].dts = TS_NONE;
            isEnd = 1;
            f->count_ts -= min( 1, f->count_ts );
        }
    }
    SignalSema( f->sema );
    return 1;
}
